"use client";

import { decodeListLocationState, encodeListLocationState, type EntityListDescriptorV1, type EntityListResultV1, type EntityListRowV1, type EntityListScopeCoordinateV1, type JsonValue, type ListFieldDescriptorV1, type ListFilterOperator, type ListFilterV1, type ListLocationStateV1, type ListSortV1 } from "@athyper/contract-platform-entity-list";
import { addRecordBookmarksOperation, ApiTransportError, entityListDescriptorOperation, entityListOperation, entityListQuery, entityListScopeQuery, recordBookmarkMembershipOperation, removeRecordBookmarksOperation, type HttpClient, type RecordBookmarkMutationV1 } from "@athyper/platform-api-client";
import { ArrowDownIcon, ArrowUpDownIcon, ArrowUpIcon, ChevronDownIcon, ColumnsIcon, DownloadIcon, FilterIcon, GripVerticalIcon, GroupIcon, LayoutIcon, LinkIcon, MoreHorizontalIcon, MoreVerticalIcon, RefreshCwIcon, ResetIcon, SearchIcon, SortIcon, StarIcon, TrashIcon } from "@athyper/platform-icons";
import { ContentHeader } from "@athyper/platform-shell";
