function ErrorState({ error, retry, compact = false }: { readonly error: ApiTransportError; readonly retry: () => void; readonly compact?: boolean }) { return <Card className={`a-entity-list__state${compact ? " a-entity-list__state--inline" : ""}`} role="alert"><Badge tone="danger">Unavailable</Badge><div><h2>{compact ? "The latest results could not be loaded" : "The list could not be loaded"}</h2><p>{error.message}</p>{error.requestId ? <small>Request ID: {error.requestId}</small> : null}</div><Button size="small" variant="secondary" onClick={retry}>Try again</Button></Card>; }
